import os
run_dir = "/root/.proma-research/e1-2026-08-27-textbook_M-s0"
for root, dirs, files in os.walk(run_dir):
    for f in files:
        p = os.path.join(root, f)
        print(p, os.path.getsize(p))

D = "/root/.proma-research/e1-2026-08-27-textbook_M-s0"

LOADER = '''import json,os
D="{d}"
PROT={prot!r}
def objs(p):
 try:
  t=open(p).read()
 except Exception:
  return []
 out=[]
 try:
  out.append(json.loads(t))
 except Exception:
  for L in t.splitlines():
   L=L.strip()
   if L:
    try: out.append(json.loads(L))
    except Exception: pass
 return out
cands=[]
for r,_,fs in os.walk(D):
 for f in fs:
  if not (f.endswith(".json") or f.endswith(".jsonl")): continue
  if f.startswith("journal"): continue
  p=os.path.join(r,f)
  mt=os.path.getmtime(p)
  for j in objs(p):
   s=json.dumps(j)
   if PROT not in s: continue
   if "evalCommand" in s: continue
   if isinstance(j,dict) and isinstance(j.get("op"),str): continue
   if '"candidate"' in s and '"protocol_label"' in s: continue
   cands.append((mt,p,j,s))
obs=[c for c in cands if '"spike_count"' in c[3]]
pool=obs if obs else cands
out={{"n_files":len(cands),"n_obs":len(obs),"prot":PROT}}
def traces(o,tr):
 if isinstance(o,dict):
  for k,v in o.items():
   if isinstance(v,list) and len(v)>40 and all(isinstance(x,(int,float)) for x in v[:5]) and min(v)<0 and max(v)<70:
    tr.append(v)
   else:
    traces(v,tr)
 elif isinstance(o,list):
  for v in o: traces(v,tr)
 return tr
def counts(o,cs):
 if isinstance(o,dict):
  for k,val in o.items():
   if k=="spike_count" and isinstance(val,(int,float)): cs.append(val)
   elif k=="spike_counts" and isinstance(val,list): cs.extend([x for x in val if isinstance(x,(int,float))])
   else: counts(val,cs)
 elif isinstance(o,list):
  for val in o: counts(val,cs)
 return cs
'''

def mkcmd(prot, body):
    script = LOADER.format(d=D, prot=prot) + body
    assert "'" not in script, "single quote in script!"
    return "printf '%s' '" + script + "' > /tmp/e.py && python3 /tmp/e.py"

# ---- P1a: adaptation ratio (late/first half counts from trace)
body_p1a = '''
if not pool:
 out["metric"]=float("nan"); out["error"]="no candidate files"
else:
 mt,p,j,s=pool[-1]
 tr=traces(j,[])
 ratios=[]; halves=[]
 for v in tr:
  n=len(v); h=n//2
  c1=sum(1 for x in v[:h] if x>0.0)
  c2=sum(1 for x in v[h:] if x>0.0)
  halves.append([c1,c2])
  if c1+c2>3: ratios.append(c2/float(max(c1,1)))
 out["halves"]=halves
 out["n_traces"]=len(tr)
 out["file"]=p
 out["metric"]=(sum(ratios)/len(ratios)) if ratios else float("nan")
print(json.dumps(out))
'''

# ---- P1b: inter-spike baseline drift (late quarter vs early quarter)
body_p1b = '''
if not pool:
 out["metric"]=float("nan"); out["error"]="no candidate files"
else:
 mt,p,j,s=pool[-1]
 tr=traces(j,[])
 drifts=[]
 for v in tr:
  n=len(v)
  early=[v[i] for i in range(n) if -85.0<v[i]<-25.0 and i<n//4]
  late=[v[i] for i in range(n) if -85.0<v[i]<-25.0 and i>=3*n//4]
  if len(early)>=3 and len(late)>=3:
   drifts.append(sum(late)/len(late)-sum(early)/len(early))
 out["drifts"]=drifts
 out["n_traces"]=len(tr)
 out["file"]=p
 out["metric"]=(sum(drifts)/len(drifts)) if drifts else float("nan")
print(json.dumps(out))
'''

# ---- P1c: spike peak amplitude trend (first half peaks - second half peaks)
body_p1c = '''
if not pool:
 out["metric"]=float("nan"); out["error"]="no candidate files"
else:
 mt,p,j,s=pool[-1]
 tr=traces(j,[])
 trends=[]
 for v in tr:
  n=len(v)
  fh=[v[i] for i in range(n) if v[i]>0.0 and i<n//2]
  sh=[v[i] for i in range(n) if v[i]>0.0 and i>=n//2]
  if len(fh)>=2 and len(sh)>=2:
   trends.append(sum(fh)/len(fh)-sum(sh)/len(sh))
 out["trends"]=trends
 out["n_traces"]=len(tr)
 out["file"]=p
 out["metric"]=(sum(trends)/len(trends)) if trends else float("nan")
print(json.dumps(out))
'''

# ---- P2: weak test diff vs 6.5
body_p2 = '''
if not pool:
 out["metric"]=float("nan"); out["error"]="no candidate files"
else:
 mt,p,j,s=pool[-1]
 cs=counts(j,[])
 out["counts"]=cs
 if cs:
  out["metric"]=sum(cs)/len(cs)-6.5
 else:
  tr=traces(j,[])
  cts=[]
  for v in tr:
   k=int(len(v)*0.86)
   cts.append(sum(1 for x in v[k:] if x>0.0))
  out["trace_counts_tail"]=cts
  out["metric"]=(sum(cts)/len(cts)-6.5) if cts else float("nan")
 out["file"]=p
print(json.dumps(out))
'''

# ---- P3: depol conditioning diff vs 36.9 (explicit count preferred; audit tail-fraction count)
body_p3 = '''
if not pool:
 out["metric"]=float("nan"); out["error"]="no candidate files"
else:
 mt,p,j,s=pool[-1]
 cs=counts(j,[])
 out["counts"]=cs
 tr=traces(j,[])
 tail=[]; whole=[]
 for v in tr:
  k=int(len(v)*0.625)
  tail.append(sum(1 for x in v[k:] if x>0.0))
  whole.append(sum(1 for x in v if x>0.0))
 out["trace_counts_tail"]=tail
 out["trace_counts_whole"]=whole
 if cs:
  out["metric"]=sum(cs)/len(cs)-36.9
 elif tail:
  out["metric"]=sum(tail)/len(tail)-36.9
 else:
  out["metric"]=float("nan")
 out["file"]=p
print(json.dumps(out))
'''

# ---- P4: hyperpol conditioning + depol test diff vs 15.9
body_p4 = '''
if not pool:
 out["metric"]=float("nan"); out["error"]="no candidate files"
else:
 mt,p,j,s=pool[-1]
 cs=counts(j,[])
 out["counts"]=cs
 if cs:
  out["metric"]=sum(cs)/len(cs)-15.9
 else:
  tr=traces(j,[])
  cts=[]
  for v in tr:
   cts.append(sum(1 for x in v if x>0.0))
  out["trace_counts"]=cts
  out["metric"]=(sum(cts)/len(cts)-15.9) if cts else float("nan")
 out["file"]=p
print(json.dumps(out))
'''

cmds = {
 "P1a": mkcmd("long step (10 uA, 300 ms)", body_p1a),
 "P1b": mkcmd("long step (10 uA, 300 ms)", body_p1b),
 "P1c": mkcmd("long step (10 uA, 300 ms)", body_p1c),
 "P2":  mkcmd("hyperpol pre-pulse + weak test (-30 uA/250 ms, gap, +6 uA)", body_p2),
 "P3":  mkcmd("depolarising conditioning + test (+15 uA/250 ms, then +12 uA)", body_p3),
 "P4":  mkcmd("hyperpol conditioning + depol test (-30 uA/250 ms, then +12 uA)", body_p4),
}
for k,v in cmds.items():
    print(k, len(v))
print(cmds["P2"][:400])

head = LOADER.format(d=D, prot=json.dumps("x"))
print("loader has quote:", "'" in head)
for name, b in [("P1a",body_p1a),("P1b",body_p1b),("P1c",body_p1c),("P2",body_p2),("P3",body_p3),("P4",body_p4)]:
    if "'" in b:
        print(name, "has quote at:", [l for l in b.splitlines() if "'" in l])

